{"command": "cd /workspace && python3 tools/synth.py && python3 - <<'EOF'
import sys; sys.path.insert(0,'/workspace/tools')
import numpy as np, glob
from wav import load_wav
for p in sorted(glob.glob('/workspace/samples/*.wav')):
    a,r=load_wav(p)
    sp=np.abs(np.fft.rfft(a*np.hanning(len(a)),8192)); fr=np.fft.rfftfreq(8192,1/r)
    cen=(sp*fr).sum()/max(sp.sum(),1e-9)
    print(f"{p.split('/')[-1]:12s} len={len(a)/r:6.3f}s  peak={np.max(np.abs(a)):.3f} rms={np.sqrt((a**2).mean()):.3f} centroid={cen:7.0f}Hz")
EOF"}

