{"command": "cd /workspace && cat > tools/song.py <<'PYEOF'
import sys, json, re, os
sys.path.insert(0,'/workspace/tools')
import numpy as np

BPM = 140
SPEED = 6
ROWS_PER_BEAT = 4
BAR = 16
PPB = 64   # rows per pattern (4 bars)
NCHAN = 16

INST = {
 1:('KICK','/workspace/samples/kick.wav'),
 2:('CLAP','/workspace/samples/clap.wav'),
 3:'HAT C',4:'HAT O',5:'CRASH',6:'TOM FM',7:'RISE FX',
 8:('ACID BS','/workspace/samples/bass.wav'),
 9:('SUB BAS','/workspace/samples/sub.wav'),
 10:('★LEAD★','/workspace/samples/lead.wav'),
 11:('SAWSTAB','/workspace/samples/stab.wav'),
 12:('FP2 PLK','/workspace/samples/pluck.wav'),
 13:('BELLCAL','/workspace/samples/bell.wav'),
 14:('PADD 1','/workspace/samples/pad.wav'),
}
for k,v in list(INST.items()):
    if isinstance(v,str): INST[k]=(v,None)

CH = dict(KICK=0, CLAP=1, HATC=2, HATO=3, BASS=4, SUB=5, ARP1=6, ARP2=7,
          LEAD=8, HRMS=9, PADLO=10, PADHI=11, STAB=12, BELL=13, TOM=14, FX=15)

NOTE_IDX = {}
_pc = {'C':0,'C#':1,'D':2,'D#':3,'E':4,'F':5,'F#':6,'G':7,'G#':8,'A':9,'A#':10,'B':11}
for name,i in _pc.items():
    for o in range(-2,8):
        NOTE_IDX[f"{name}{o}"] = (o+2)*12+i     # internal absolute semitone, C0-based
def N(s):
    """'A-2' -> absolute semitone index"""
    s=s.strip()
    if s in NOTE_IDX: return NOTE_IDX[s]
    m=re.match(r'^([A-G][#]?)(-?\d+)$', s.replace('-',' ').replace(' ',''))
    raise ValueError(s)
def nm(abs_semi):
    """reverse map to name string with tracker label"""
    o = abs_semi//12 - 2
    i = abs_semi % 12
    inv = {v:k for k,v in _pc.items()}
    return f"{inv[i]}-{o}"

# scale helpers ----------------------------------------------------------
AMIN = [0,2,3,5,7,8,10]           # A natural minor degrees
AMIN_H = [0,2,3,5,7,8,11]         # A harmonic minor (for E major chord)
def deg_to_semi(base, scale, deg):
    octv, i = divmod(deg, 7)
    return base + octv*12 + scale[i]
def find_deg(base, scale, semi):
    """nearest scale degree for a semitone offset"""
    for d in range(-2, 16):
        if deg_to_semi(base, scale, d) == semi: return d
    return None

# chords: (root_abs, [interval set for pads])
def cn(s): return N(s)
CHORDS = {
 'Am':  dict(root=N('A-2'), tones=[0,3,7,12], pad=[N('A-3'),N('C-4'),N('E-4')], arp=[0,3,7,12,7,3], bass=N('A-2'), color='min'),
 'F':   dict(root=N('F-2'), tones=[0,4,9,12], pad=[N('F-3'),N('A-3'),N('C-4')], arp=[0,4,9,12,9,4], bass=N('F-2'), color='maj'),
 'G':   dict(root=N('G-2'), tones=[0,4,7,14], pad=[N('G-3'),N('B-3'),N('D-4')], arp=[0,4,7,12,7,4], bass=N('G-2'), color='maj'),
 'E':   dict(root=N('E-2'), tones=[0,4,7,12], pad=[N('E-3'),N('G#-3'),N('B-3')], arp=[0,4,7,12,7,4], bass=N('E-2'), color='maj'),
 'C':   dict(root=N('C-3'), tones=[0,4,7,12], pad=[N('C-4'),N('E-4'),N('G-4')], arp=[0,4,7,12,7,4], bass=N('C-3'), color='maj'),
 'Dm':  dict(root=N('D-2'), tones=[0,3,7,10], pad=[N('D-3'),N('F-3'),N('A-3')], arp=[0,3,7,10,7,3], bass=N('D-2'), color='min'),
 'Em':  dict(root=N('E-2'), tones=[0,3,7,10], pad=[N('E-3'),N('G-3'),N('B-3')], arp=[0,3,7,12,7,3], bass=N('E-2'), color='min'),
 'Bb':  dict(root=N('Bb-2'), tones=[0,4,7,12], pad=[N('Bb-3'),N('D-4'),N('F-4')], arp=[0,4,7,12,7,4], bass=N('Bb-2'), color='maj'),
}

# pattern storage: pats[(patidx,row,ch)] = dict
cells = {}
def put(pat, row, ch, note=None, inst=None, vol=None, name=None):
    if note is not None:
        note = N(note) if isinstance(note,str) else note
    key=(pat,row,ch)
    d=cells.setdefault(key, {})
    if note is not None: d['note']=note
    if inst is not None: d['inst']=inst
    if vol is not None: d['vol']=vol
    return d

def clear_section(pat):
    for k in [k for k in cells if k[0]==pat]: del cells[k]

# --------------- part writers ---------------
def grid(pat, ch, bar_range, s, inst, base_vol=64, vel_map=None, transpose=0):
    """s: 16-char string per bar; 'x' hit, 'X' accent, 'o' soft, '-' rest"""
    for bi in bar_range:
        base = bi*BAR
        for r,c in enumerate(s):
            if c=='-' or c=='.': continue
            v = base_vol
            if c=='X': v = min(64, int(base_vol*1.0))
            elif c=='x': v = int(base_vol*0.92)
            elif c=='o': v = int(base_vol*0.62)
            put(pat, base+r, ch, inst=inst, vol=v, transpose=transpose)

def drumline(pat, bars, kind):
    K,C,HC,HO,T,F = CH['KICK'],CH['CLAP'],CH['HATC'],CH['HATO'],CH['TOM'],CH['FX']
    if kind=='none': return
    if kind=='intro':
        grid(pat, bars, K, 'x.......x.......', 1, 62)
        grid(pat, bars, HC, '..x...x...x...x.', 3, 34)
    elif kind=='kick4':
        grid(pat, bars, K, 'x...x...x...x...', 1, 62)
        grid(pat, bars, C, '....x.......x...', 2, 50)
        grid(pat, bars, HC, '..x...x...x...x.', 3, 30)
        grid(pat, bars, HO, '..............x.', 4, 26)
    elif kind=='drive':
        grid(pat, bars, K, 'x...x...x..x.x..', 1, 64)
        grid(pat, bars, C, '....x.......x...', 2, 52)
        grid(pat, bars, HC, 'x.x.x.x.x.x.x.xo', 3, 30)
        grid(pat, bars, HO, '......x.......x.', 4, 28)
    elif kind=='full':
        grid(pat, bars, K, 'x...x...x...x...', 1, 64)
        grid(pat, bars, C, '....x.......x...', 2, 54)
        grid(pat, bars, HC, '..x.o.x.o..x.o.x', 3, 32)
        grid(pat, bars, HO, '......x.......x.', 4, 30)
    elif kind=='chorus':
        grid(pat, bars, K, 'x...x..ox...x..o', 1, 64)
        grid(pat, bars, C, '....x.......x..x', 2, 54)
        grid(pat, bars, HC, 'o.x.o.x.o..x.x.x', 3, 34)
        grid(pat, bars, HO, '......x.......x.', 4, 30)
        grid(pat, bars, T, '------------x-x-', 6, 26)
    elif kind=='break':
        grid(pat, bars, K, 'x.......x.......', 1, 56)
        grid(pat, bars, C, '....x.......x...', 2, 44)
        grid(pat, bars, HC, '..x...x...x...x.', 3, 24)

def fill(pat, start_row, kind='16th', inst=2, vol=52, up=True):
    """percussive fill starting at row"""
    if kind=='16th':
        for i,r in enumerate(range(start_row, min(start_row+16, PPB), 2)):
            put(pat, r, CH['TOM'] if i%2==0 else CH['CLAP'], note='D-4' if i%2==0 else 'C-4',
