import sys, json, subprocess, time; sys.path.insert(0,'/workspace/tools')
import song
import numpy as np
from wav import load_wav

def emit_filtered(chans, path, batch, pats=(6,8)):
    song.build()
    calls=[{"name":"module_new","arguments":{"channels":song.NCHAN,"name":"iso"}}]
    for i,(n_,f) in song.SAMPLES.items():
        calls.append({"name":"instrument_set","arguments":{"instrument":i,"name":n_}})
        if f: calls.append({"name":"sample_load","arguments":{"path":f,"instrument":i,"sample":0}})
    for pi,p in enumerate(pats):
        calls.append({"name":"pattern_set_length","arguments":{"pattern":p,"rows":song.PPB}})
        for (pp,r,c),d in sorted(song.cells.items()):
            if pp!=p or c not in chans: continue
            arg={"pattern":p,"row":r,"channel":c}
            if 'note' in d: arg["note"]=song.nm(d['note'])
            if 'inst' in d: arg["instrument"]=d['inst']
            if 'vol' in d: arg["volume"]=d['vol']
            calls.append({"name":"pattern_set_cell","arguments":arg})
        calls.append({"name":"order_set","arguments":{"position":pi,"pattern":p}})
    calls.append({"name":"song_set","arguments":{"bpm":song.BPM,"speed":song.SPEED,"length":len(pats),"loop_start":0}})
    calls.append({"name":"module_render","arguments":{"path":path,"rate":22050,"bits":16,"loops":1}})
    json.dump(calls, open(batch,'w'))

GROUPS = {name: [song.CH[k] for k in keys] for name,keys in {
 'kick':['KICK'], 'clap':['CLAP'], 'hat':['HATC','HATO'], 'bass':['BASS'], 'sub':['SUB'],
 'arp':['ARP1','ARP2'], 'lead':['LEAD'], 'hrms':['HRMS'], 'pad':['PADLO','PADHI'],
 'stab':['STAB'], 'bell':['BELL'], 'tom':['TOM'], 'fx':['FX']}.items()}

if __name__=='__main__':
    t=time.time()
    PBRK, PCHOR = 6, 8
    dur=song.PPB*song.SPEED*2.5/song.BPM
    for name,chans in GROUPS.items():
        emit_filtered(chans, f'/tmp/iso_{name}.wav', '/tmp/iso.json', pats=(PBRK,PCHOR))
        subprocess.run(['ft2','batch','/tmp/iso.json'], capture=True if False else True)
        a,r=load_wav(f'/tmp/iso_{name}.wav')
        seg1=a[:int(dur*r)]
        for lo,hi in [(20,80),(80,160),(160,400),(400,1000),(1000,2500),(2500,7000)]:
            pass
        def band(seg,lo,hi):
            X=np.fft.rfft(seg,len(seg)); fr=np.fft.rfftfreq(len(seg),1/r)
            Y=X.copy(); Y[(fr<lo)|(fr>=hi)]=0
            return np.sqrt((np.fft.irfft(Y,len(seg))**2).mean())
        rows=[]
        for t0,t1 in [(0.2,dur-0.2),(dur+0.2,2*dur-0.2)]:
            seg=a[int(t0*r):int(t1*r)]
            rms=np.sqrt((seg**2).mean())
            lows=sum(band(seg,lo,hi) for lo,hi in [(20,80),(80,160)])
            mids=sum(band(seg,lo,hi) for lo,hi in [(160,400),(400,1000),(1000,2500)])
            hi_=band(seg,2500,10000)
            rows.append((rms,lows,mids,hi_))
        print(f"{name:6s} brk: rms={rows[0][0]:.4f} low={rows[0][1]:.4f} mid={rows[0][2]:.4f} hi={rows[0][3]:.4f} "
              f"| chor: rms={rows[1][0]:.4f} low={rows[1][1]:.4f} mid={rows[1][2]:.4f} hi={rows[1][3]:.4f}")
    print("elapsed",round(time.time()-t,1))
