{"command": "cd /workspace && python3 - <<'EOF'
import sys; sys.path.insert(0,'/workspace/tools')
import song
song.build()
BAR=16
# chord tone tables (pitch classes, 0=A)
def pcs(root_abs, tones): return set((root_abs+t)%12 for t in tones)
CHORD_PCS={k:pcs(v['root'],v['tones']) for k,v in song.CHORDS.items()}
PROG={0:['Am','F','G','E'],1:['Am','F','G','E'],2:['Am','F','G','E'],3:['Am','F','G','E'],
      4:['Dm','Am','F','E'],5:['Dm','Am','F','E'],6:['Am','G','F','E'],7:['Am','G','F','E'],
      8:['Am','F','G','E'],9:['Am','F','G','E'],10:['F','G','C','Em'],11:['F','G','C','Em'],
      12:['Am','G','F','E'],13:['Am','F','G','E'],14:['Am','F','G','E'],15:['Am','F','G','Am'],16:['Am','F','G','Am']}
# scale allowance: A minor family + G# (harmonic) + F# (Em 9th) etc.
ALLOW = set()
for p,prog in PROG.items():
    for bi,ch in enumerate(prog):
        chord=CHORD_PCS[ch]
        # notes on melodic channels in this bar
        for c in (song.CH['LEAD'],song.CH['HRMS'],song.CH['BELL']):
            for (pp,r,cc),d in song.cells.items():
                if pp!=p or cc!=c: continue
                if not (bi*BAR<=r<(bi+1)*BAR): continue
                n=d['note']%12
                if n not in chord:
                    # allowed non-chord tones: scale degrees of A minor + passing
                    if n not in ALLOW: ALLOW.add((n,ch,p,r,song.nm(d['note'])))
print("Non-chord melodic notes (pitchclass, chord, pattern, row, note):")
for x in sorted(ALLOW, key=lambda x:(x[2],x[3])): print("  ", x)
EOF"}

